mapper.select:
SELECT * FROM ( SELECT MIN(CR.CANCEL_NO) AS CANCEL_NO, MIN(CR.ORDER_ITEM_NO) AS ORDER_ITEM_NO, CR.ORDER_NO, MIN(CR.MEMBER_NO) AS MEMBER_NO, NULL AS BUSINESS_NO, NULL AS PRODUCT_NO, '전체 상품 (' || COUNT(*) || '건)' AS PRODUCT_NAME, NULL AS PRODUCT_PRICE, SUM(OI.QUANTITY) AS QUANTITY, SUM(CR.REFUND_AMOUNT) AS CANCEL_AMOUNT, MIN(CR.REASON) AS REASON, CASE WHEN SUM(CASE WHEN CR.STATUS = 'REJECTED' THEN 1 ELSE 0 END) > 0 THEN 'REJECTED' WHEN SUM(CASE WHEN CR.STATUS = 'WAITING' THEN 1 ELSE 0 END) > 0 THEN 'WAITING' ELSE 'APPROVED' END AS STATUS, MIN(CR.CREATED_AT) AS CREATED_AT, MAX(CR.PROCESSED_AT) AS PROCESSED_AT, MAX(CR.REJECT_REASON) AS REJECT_REASON, CR.CANCEL_TYPE, CR.CANCEL_GROUP_NO, SUM(CR.REFUND_AMOUNT) AS REFUND_AMOUNT, COUNT(*) AS ITEM_COUNT, CASE WHEN MIN(CASE WHEN NVL(D.STATUS, 'CONFIRMED') = 'DELIVERED' THEN 1 ELSE 0 END) = 1 THEN 'REFUND' ELSE 'CANCEL' END AS HISTORY_TYPE FROM CANCEL_REQUEST CR JOIN ORDER_ITEM OI ON OI.ORDER_ITEM_NO = CR.ORDER_ITEM_NO LEFT JOIN DELIVERY D ON D.ORDER_ITEM_NO = CR.ORDER_ITEM_NO WHERE CR.MEMBER_NO = #{memberNo} AND CR.CANCEL_TYPE = 'FULL' GROUP BY CR.ORDER_NO, CR.CANCEL_TYPE, CR.CANCEL_GROUP_NO
UNION ALL
SELECT CR.CANCEL_NO, CR.ORDER_ITEM_NO, CR.ORDER_NO, CR.MEMBER_NO, OI.BUSINESS_NO, OI.PRODUCT_NO, P.PRODUCT_NAME, OI.PRODUCT_PRICE, OI.QUANTITY, CR.REFUND_AMOUNT AS CANCEL_AMOUNT, CR.REASON, CR.STATUS, CR.CREATED_AT, CR.PROCESSED_AT, CR.REJECT_REASON, CR.CANCEL_TYPE, CR.CANCEL_GROUP_NO, CR.REFUND_AMOUNT, 1 AS ITEM_COUNT, CASE WHEN NVL(D.STATUS, 'CONFIRMED') = 'DELIVERED' THEN 'REFUND' ELSE 'CANCEL' END AS HISTORY_TYPE FROM CANCEL_REQUEST CR JOIN ORDER_ITEM OI ON OI.ORDER_ITEM_NO = CR.ORDER_ITEM_NO JOIN PRODUCT P ON P.PRODUCT_NO = OI.PRODUCT_NO LEFT JOIN DELIVERY D ON D.ORDER_ITEM_NO = CR.ORDER_ITEM_NO WHERE CR.MEMBER_NO = #{memberNo} AND CR.CANCEL_TYPE = 'PARTIAL' ) H
H.HISTORY_TYPE = #{historyType}
AND H.STATUS = #{status}
AND H.CREATED_AT >= #{startDate}
AND H.CREATED_AT < #{endDate} + 1
ORDER BY H.CREATED_AT DESC, H.CANCEL_NO DESC

SELECT COUNT(*) FROM ( SELECT 1 FROM CANCEL_REQUEST CR JOIN ORDER_ITEM OI ON OI.ORDER_ITEM_NO = CR.ORDER_ITEM_NO JOIN PRODUCT P ON P.PRODUCT_NO = OI.PRODUCT_NO WHERE OI.BUSINESS_NO = #{businessNo} GROUP BY CR.ORDER_NO, OI.BUSINESS_NO, CR.CANCEL_TYPE, CR.CANCEL_GROUP_NO
HAVING CASE WHEN SUM(CASE WHEN CR.STATUS = 'REJECTED' THEN 1 ELSE 0 END) > 0 THEN 'REJECTED' WHEN SUM(CASE WHEN CR.STATUS = 'WAITING' THEN 1 ELSE 0 END) > 0 THEN 'WAITING' ELSE 'APPROVED' END = #{status}
)

mapper.update:
UPDATE CANCEL_REQUEST CR
   SET CR.STATUS = 'APPROVED', CR.PROCESSED_AT = SYSDATE, CR.REJECT_REASON = NULL
 WHERE CR.CANCEL_GROUP_NO = #{cancelGroupNo}
   AND CR.CANCEL_TYPE = 'FULL'
   AND CR.STATUS = 'WAITING'
   AND EXISTS (
       SELECT 1 FROM ORDER_ITEM OI
        WHERE OI.ORDER_ITEM_NO = CR.ORDER_ITEM_NO
          AND OI.BUSINESS_NO = #{businessNo}
   )

UPDATE CANCEL_REQUEST
   SET STATUS = 'REJECTED', PROCESSED_AT = SYSDATE, REJECT_REASON = #{rejectReason}
 WHERE CANCEL_NO = #{cancelNo}
   AND STATUS = 'WAITING'

UPDATE CANCEL_REQUEST
   SET STATUS = 'REJECTED', PROCESSED_AT = SYSDATE, REJECT_REASON = #{rejectReason}
 WHERE CANCEL_GROUP_NO = #{cancelGroupNo}
   AND CANCEL_TYPE = 'FULL'
   AND STATUS IN ('WAITING', 'APPROVED')
